import { Object3D, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
	// root container
	const root = new Object3D();

	// geometry (unit plane)
	const geometry = new PlaneGeometry(1, 1);

	// load brushed‑metal texture
	const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

	// basic node material with texture map
	const material = new MeshBasicNodeMaterial({ map: texture });

	// mesh
	const plane = new Mesh(geometry, material);

	// apply transforms from config (fallback to defaults)
	const pos = config.position ?? { x: 0, y: 0, z: 0 };
	const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
	const scl = config.scale ?? { x: 1, y: 1, z: 1 };

	plane.position.set(pos.x, pos.y, pos.z);
	plane.rotation.set(rot.x, rot.y, rot.z);
	plane.scale.set(scl.x, scl.y, scl.z);

	// add to hierarchy
	root.add(plane);

	// --------- Interaction ----------
	// hover lift (rise‑in) – subtle 0.15 scene units
	const hoverTween = gsap.to(plane.position, {
		y: plane.position.y + 0.15,
		duration: 0.7,
		ease: 'power3.out',
		paused: true
	});

	// press‑down on click (scale down briefly)
	const pressTween = gsap.to(plane.scale, {
		x: 0.97,
		y: 0.97,
		z: 0.97,
		duration: 0.12,
		ease: 'back.out',
		paused: true
	});

	plane.userData.handlers = {
		hoverEnter: () => hoverTween.play(),
		hoverLeave: () => hoverTween.reverse(),
		mouseDown: () => pressTween.play(),
		mouseUp: () => pressTween.reverse(),
		click: () => {
			if (typeof ctx.emit === 'function') {
				ctx.emit('hub-collection.select');
			}
		}
	};

	// --------- Cleanup ----------
	root.userData.cleanup = () => {
		gsap.killTweensOf(plane.position);
		gsap.killTweensOf(plane.scale);
		geometry.dispose();
		material.dispose();
		// texture may be shared; dispose only if owned
		if (texture && texture.dispose) texture.dispose();
	};

	return root;
}
